import type { FastifyReply } from "fastify";

// The RealWorld error envelope: { "errors": { "<field>": ["<message>"] } }.
export type ErrorBody = { errors: Record<string, string[]> };

export function errorBody(field: string, message: string): ErrorBody {
  return { errors: { [field]: [message] } };
}

// A typed error carrying an HTTP status and a RealWorld error envelope.
export class ApiError extends Error {
  status: number;
  body: ErrorBody;

  constructor(status: number, field: string, message: string) {
    super(message);
    this.status = status;
    this.body = errorBody(field, message);
  }
}

export function sendError(reply: FastifyReply, err: ApiError): FastifyReply {
  return reply.status(err.status).send(err.body);
}

// Common error constructors used across routes.
export const tokenMissing = () => new ApiError(401, "token", "is missing");
export const articleNotFound = () => new ApiError(404, "article", "not found");
export const commentNotFound = () => new ApiError(404, "comment", "not found");
