import jwt from "jsonwebtoken";
import bcrypt from "bcryptjs";
import type { FastifyRequest } from "fastify";
import { ApiError, tokenMissing } from "./errors.js";

const JWT_SECRET = process.env.JWT_SECRET || "realworld-dev-secret-change-me";

export interface TokenPayload {
  id: number;
  username: string;
}

export function signToken(payload: TokenPayload): string {
  return jwt.sign(payload, JWT_SECRET, { expiresIn: "30d" });
}

export function hashPassword(password: string): Promise<string> {
  return bcrypt.hash(password, 10);
}

export function verifyPassword(password: string, hash: string): Promise<boolean> {
  return bcrypt.compare(password, hash);
}

// Extracts the raw token from an "Authorization: Token <jwt>" header.
function extractToken(request: FastifyRequest): string | null {
  const header = request.headers.authorization;
  if (!header) return null;
  const [scheme, value] = header.split(" ");
  if (!value || !/^(Token|Bearer)$/i.test(scheme)) return null;
  return value.trim();
}

// Returns the authenticated user id, or null if no valid token is present.
export function optionalUserId(request: FastifyRequest): number | null {
  const token = extractToken(request);
  if (!token) return null;
  try {
    const payload = jwt.verify(token, JWT_SECRET) as TokenPayload;
    return payload.id;
  } catch {
    return null;
  }
}

// Returns the authenticated user id, or throws a 401 when the token is missing
// or invalid.
export function requireUserId(request: FastifyRequest): number {
  const token = extractToken(request);
  if (!token) throw tokenMissing();
  try {
    const payload = jwt.verify(token, JWT_SECRET) as TokenPayload;
    return payload.id;
  } catch {
    throw new ApiError(401, "token", "is invalid");
  }
}

