import type { FastifyInstance } from "fastify";
import { Prisma } from "@prisma/client";
import { prisma } from "../lib/prisma.js";
import { ApiError } from "../lib/errors.js";
import { hashPassword, verifyPassword, requireUserId } from "../lib/auth.js";
import { userJson } from "../lib/views.js";

const MIN_PASSWORD_LENGTH = 8;

function asString(value: unknown): string | undefined {
  return typeof value === "string" ? value : undefined;
}

export async function userRoutes(app: FastifyInstance) {
  // Registration
  app.post("/users", async (request, reply) => {
    const input = ((request.body as any)?.user ?? {}) as Record<string, unknown>;
    const username = asString(input.username);
    const email = asString(input.email);
    const password = asString(input.password);

    if (!username) throw new ApiError(422, "username", "can't be blank");
    if (!email) throw new ApiError(422, "email", "can't be blank");
    if (!password) throw new ApiError(422, "password", "can't be blank");

    if (await prisma.user.findUnique({ where: { username } })) {
      throw new ApiError(409, "username", "has already been taken");
    }
    if (await prisma.user.findUnique({ where: { email } })) {
      throw new ApiError(409, "email", "has already been taken");
    }

    const user = await prisma.user.create({
      data: { username, email, password: await hashPassword(password) },
    });
    return reply.status(201).send(userJson(user));
  });

  // Login
  app.post("/users/login", async (request, reply) => {
    const input = ((request.body as any)?.user ?? {}) as Record<string, unknown>;
    const email = asString(input.email);
    const password = asString(input.password);

    if (!email) throw new ApiError(422, "email", "can't be blank");
    if (!password) throw new ApiError(422, "password", "can't be blank");

    const user = await prisma.user.findUnique({ where: { email } });
    if (!user || !(await verifyPassword(password, user.password))) {
      throw new ApiError(401, "credentials", "invalid");
    }
    return reply.send(userJson(user));
  });

  // Current user
  app.get("/user", async (request, reply) => {
    const userId = requireUserId(request);
    const user = await prisma.user.findUnique({ where: { id: userId } });
    if (!user) throw new ApiError(401, "token", "is invalid");
    return reply.send(userJson(user));
  });

  // Update current user
  app.put("/user", async (request, reply) => {
    const userId = requireUserId(request);
    const input = ((request.body as any)?.user ?? {}) as Record<string, unknown>;
    const data: Prisma.UserUpdateInput = {};

    // username / email: required-when-present, reject blank or null.
    if ("username" in input) {
      const username = asString(input.username);
      if (!username) throw new ApiError(422, "username", "can't be blank");
      data.username = username;
    }
    if ("email" in input) {
      const email = asString(input.email);
      if (!email) throw new ApiError(422, "email", "can't be blank");
      data.email = email;
    }
    if ("password" in input) {
      const password = asString(input.password);
      if (!password) throw new ApiError(422, "password", "can't be blank");
      if (password.length < MIN_PASSWORD_LENGTH) {
        throw new ApiError(422, "password", "is too short (minimum is 8 characters)");
      }
      data.password = await hashPassword(password);
    }
    // bio / image: nullable. Empty string normalises to null.
    if ("bio" in input) {
      const bio = asString(input.bio);
      data.bio = bio ? bio : null;
    }
    if ("image" in input) {
      const image = asString(input.image);
      data.image = image ? image : null;
    }

    try {
      const user = await prisma.user.update({ where: { id: userId }, data });
      return reply.send(userJson(user));
    } catch (err) {
      if (err instanceof Prisma.PrismaClientKnownRequestError && err.code === "P2002") {
        const target = (err.meta?.target as string[] | undefined)?.[0] ?? "username";
        throw new ApiError(409, target, "has already been taken");
      }
      throw err;
    }
  });
}

