import type { FastifyInstance } from "fastify";
import { prisma } from "../lib/prisma.js";
import { profileNotFound } from "../lib/errors.js";
import { optionalUserId, requireUserId } from "../lib/auth.js";
import { profileJson } from "../lib/views.js";

const profileInclude = { followedBy: { select: { id: true } } } as const;

export async function profileRoutes(app: FastifyInstance) {
  // Get profile (auth optional)
  app.get("/profiles/:username", async (request, reply) => {
    const { username } = request.params as { username: string };
    const currentUserId = optionalUserId(request);
    const user = await prisma.user.findUnique({
      where: { username },
      include: profileInclude,
    });
    if (!user) throw profileNotFound();
    return reply.send(profileJson(user, currentUserId));
  });

  // Follow user
  app.post("/profiles/:username/follow", async (request, reply) => {
    const currentUserId = requireUserId(request);
    const { username } = request.params as { username: string };
    const target = await prisma.user.findUnique({ where: { username } });
    if (!target) throw profileNotFound();

    const user = await prisma.user.update({
      where: { id: target.id },
      data: { followedBy: { connect: { id: currentUserId } } },
      include: profileInclude,
    });
    return reply.send(profileJson(user, currentUserId));
  });

  // Unfollow user
  app.delete("/profiles/:username/follow", async (request, reply) => {
    const currentUserId = requireUserId(request);
    const { username } = request.params as { username: string };
    const target = await prisma.user.findUnique({ where: { username } });
    if (!target) throw profileNotFound();

    const user = await prisma.user.update({
      where: { id: target.id },
      data: { followedBy: { disconnect: { id: currentUserId } } },
      include: profileInclude,
    });
    return reply.send(profileJson(user, currentUserId));
  });
}

