import type { FastifyInstance } from "fastify";
import { Prisma } from "@prisma/client";
import { prisma } from "../lib/prisma.js";
import { ApiError, articleNotFound, articleForbidden } from "../lib/errors.js";
import { optionalUserId, requireUserId } from "../lib/auth.js";
import { articleJson, articlePayload, articleInclude } from "../lib/views.js";

function asString(value: unknown): string | undefined {
  return typeof value === "string" ? value : undefined;
}

// Turns a title into a URL-safe slug and appends a short random suffix so that
// duplicate titles still produce unique slugs.
function slugify(title: string): string {
  const base = title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  const suffix = Math.random().toString(36).slice(2, 8);
  return `${base || "article"}-${suffix}`;
}

// Normalises limit/offset query params into safe integers.
function paginationParams(query: any): { take: number; skip: number } {
  const limit = parseInt(query?.limit, 10);
  const offset = parseInt(query?.offset, 10);
  return {
    take: Number.isFinite(limit) && limit > 0 ? limit : 20,
    skip: Number.isFinite(offset) && offset > 0 ? offset : 0,
  };
}

const listOrder: Prisma.ArticleOrderByWithRelationInput[] = [
  { createdAt: "desc" },
  { id: "desc" },
];

async function connectTags(names: string[]) {
  const unique = [...new Set(names)];
  return Promise.all(
    unique.map((name) =>
      prisma.tag.upsert({ where: { name }, update: {}, create: { name } }),
    ),
  ).then((tags) => tags.map((t) => ({ id: t.id })));
}

export async function articleRoutes(app: FastifyInstance) {
  // List articles (auth optional)
  app.get("/articles", async (request, reply) => {
    const currentUserId = optionalUserId(request);
    const query = request.query as any;
    const { take, skip } = paginationParams(query);

    const where: Prisma.ArticleWhereInput = {};
    if (asString(query.tag)) where.tags = { some: { name: query.tag } };
    if (asString(query.author)) where.author = { username: query.author };
    if (asString(query.favorited)) {
      where.favoritedBy = { some: { username: query.favorited } };
    }

    const [articles, articlesCount] = await Promise.all([
      prisma.article.findMany({ where, orderBy: listOrder, take, skip, include: articleInclude }),
      prisma.article.count({ where }),
    ]);

    return reply.send({
      articles: articles.map((a) => articlePayload(a, currentUserId)),
      articlesCount,
    });
  });

  // Feed (auth required)
  app.get("/articles/feed", async (request, reply) => {
    const currentUserId = requireUserId(request);
    const { take, skip } = paginationParams(request.query as any);

    const where: Prisma.ArticleWhereInput = {
      author: { followedBy: { some: { id: currentUserId } } },
    };
    const [articles, articlesCount] = await Promise.all([
      prisma.article.findMany({ where, orderBy: listOrder, take, skip, include: articleInclude }),
      prisma.article.count({ where }),
    ]);

    return reply.send({
      articles: articles.map((a) => articlePayload(a, currentUserId)),
      articlesCount,
    });
  });

  // Create article (auth required)
  app.post("/articles", async (request, reply) => {
    const currentUserId = requireUserId(request);
    const input = ((request.body as any)?.article ?? {}) as Record<string, unknown>;
    const title = asString(input.title);
    const description = asString(input.description);
    const body = asString(input.body);

    if (!title) throw new ApiError(422, "title", "can't be blank");
    if (!description) throw new ApiError(422, "description", "can't be blank");
    if (!body) throw new ApiError(422, "body", "can't be blank");

    const tagList = Array.isArray(input.tagList)
      ? (input.tagList as unknown[]).filter((t): t is string => typeof t === "string")
      : [];

    const article = await prisma.article.create({
      data: {
        slug: slugify(title),
        title,
        description,
        body,
        authorId: currentUserId,
        tags: { connect: await connectTags(tagList) },
      },
      include: articleInclude,
    });
    return reply.status(201).send(articleJson(article, currentUserId));
  });

  // Get single article (auth optional)
  app.get("/articles/:slug", async (request, reply) => {
    const currentUserId = optionalUserId(request);
    const { slug } = request.params as { slug: string };
    const article = await prisma.article.findUnique({ where: { slug }, include: articleInclude });
    if (!article) throw articleNotFound();
    return reply.send(articleJson(article, currentUserId));
  });

  // Update article (auth required, author only)
  app.put("/articles/:slug", async (request, reply) => {
    const currentUserId = requireUserId(request);
    const { slug } = request.params as { slug: string };
    const existing = await prisma.article.findUnique({ where: { slug } });
    if (!existing) throw articleNotFound();
    if (existing.authorId !== currentUserId) throw articleForbidden();

    const input = ((request.body as any)?.article ?? {}) as Record<string, unknown>;
    const data: Prisma.ArticleUpdateInput = {};

    if ("title" in input) {
      const title = asString(input.title);
      if (!title) throw new ApiError(422, "title", "can't be blank");
      data.title = title;
      data.slug = slugify(title);
    }
    if ("description" in input) {
      const description = asString(input.description);
      if (!description) throw new ApiError(422, "description", "can't be blank");
      data.description = description;
    }
    if ("body" in input) {
      const body = asString(input.body);
      if (!body) throw new ApiError(422, "body", "can't be blank");
      data.body = body;
    }
    if ("tagList" in input) {
      if (!Array.isArray(input.tagList)) {
        throw new ApiError(422, "tagList", "must be an array");
      }
      const names = (input.tagList as unknown[]).filter(
        (t): t is string => typeof t === "string",
      );
      data.tags = { set: await connectTags(names) };
    }
    data.updatedAt = new Date();

    const article = await prisma.article.update({
      where: { slug },
      data,
      include: articleInclude,
    });
    return reply.send(articleJson(article, currentUserId));
  });

  // Delete article (auth required, author only)
  app.delete("/articles/:slug", async (request, reply) => {
    const currentUserId = requireUserId(request);
    const { slug } = request.params as { slug: string };
    const existing = await prisma.article.findUnique({ where: { slug } });
    if (!existing) throw articleNotFound();
    if (existing.authorId !== currentUserId) throw articleForbidden();

    await prisma.article.delete({ where: { slug } });
    return reply.status(204).send();
  });

  // Favorite article (auth required)
  app.post("/articles/:slug/favorite", async (request, reply) => {
    const currentUserId = requireUserId(request);
    const { slug } = request.params as { slug: string };
    if (!(await prisma.article.findUnique({ where: { slug } }))) throw articleNotFound();

    const article = await prisma.article.update({
      where: { slug },
      data: { favoritedBy: { connect: { id: currentUserId } } },
      include: articleInclude,
    });
    return reply.send(articleJson(article, currentUserId));
  });

  // Unfavorite article (auth required)
  app.delete("/articles/:slug/favorite", async (request, reply) => {
    const currentUserId = requireUserId(request);
    const { slug } = request.params as { slug: string };
    if (!(await prisma.article.findUnique({ where: { slug } }))) throw articleNotFound();

    const article = await prisma.article.update({
      where: { slug },
      data: { favoritedBy: { disconnect: { id: currentUserId } } },
      include: articleInclude,
    });
    return reply.send(articleJson(article, currentUserId));
  });
}

