import type { FastifyInstance } from "fastify";
import { prisma } from "../lib/prisma.js";
import { ApiError, articleNotFound, commentNotFound, commentForbidden } from "../lib/errors.js";
import { optionalUserId, requireUserId } from "../lib/auth.js";
import { commentJson, commentPayload, commentInclude } from "../lib/views.js";

function asString(value: unknown): string | undefined {
  return typeof value === "string" ? value : undefined;
}

export async function commentRoutes(app: FastifyInstance) {
  // Add comment (auth required)
  app.post("/articles/:slug/comments", async (request, reply) => {
    const currentUserId = requireUserId(request);
    const { slug } = request.params as { slug: string };
    const input = ((request.body as any)?.comment ?? {}) as Record<string, unknown>;
    const body = asString(input.body);
    if (!body) throw new ApiError(422, "body", "can't be blank");

    const article = await prisma.article.findUnique({ where: { slug } });
    if (!article) throw articleNotFound();

    const comment = await prisma.comment.create({
      data: { body, articleId: article.id, authorId: currentUserId },
      include: commentInclude,
    });
    return reply.status(201).send(commentJson(comment, currentUserId));
  });

  // List comments (auth optional)
  app.get("/articles/:slug/comments", async (request, reply) => {
    const currentUserId = optionalUserId(request);
    const { slug } = request.params as { slug: string };
    const article = await prisma.article.findUnique({ where: { slug } });
    if (!article) throw articleNotFound();

    const comments = await prisma.comment.findMany({
      where: { articleId: article.id },
      orderBy: [{ createdAt: "desc" }, { id: "desc" }],
      include: commentInclude,
    });
    return reply.send({
      comments: comments.map((c) => commentPayload(c, currentUserId)),
    });
  });

  // Delete comment (auth required, author only)
  app.delete("/articles/:slug/comments/:id", async (request, reply) => {
    const currentUserId = requireUserId(request);
    const { slug, id } = request.params as { slug: string; id: string };

    const article = await prisma.article.findUnique({ where: { slug } });
    if (!article) throw articleNotFound();

    const comment = await prisma.comment.findFirst({
      where: { id: Number(id), articleId: article.id },
    });
    if (!comment) throw commentNotFound();
    if (comment.authorId !== currentUserId) throw commentForbidden();

    await prisma.comment.delete({ where: { id: comment.id } });
    return reply.status(204).send();
  });
}

