import Fastify, { type FastifyInstance } from "fastify";
import { ApiError } from "./lib/errors.js";
import { userRoutes } from "./routes/users.js";
import { profileRoutes } from "./routes/profiles.js";
import { articleRoutes } from "./routes/articles.js";
import { commentRoutes } from "./routes/comments.js";
import { tagRoutes } from "./routes/tags.js";

export function buildApp(): FastifyInstance {
  const app = Fastify({ logger: false });

  // Centralised error handling that always emits the RealWorld error envelope.
  app.setErrorHandler((error, _request, reply) => {
    if (error instanceof ApiError) {
      return reply.status(error.status).send(error.body);
    }
    // Malformed JSON and other client errors.
    if (typeof error.statusCode === "number" && error.statusCode >= 400 && error.statusCode < 500) {
      return reply.status(error.statusCode).send({ errors: { body: [error.message] } });
    }
    reply.log.error(error);
    return reply.status(500).send({ errors: { body: ["internal server error"] } });
  });

  app.setNotFoundHandler((_request, reply) => {
    return reply.status(404).send({ errors: { body: ["not found"] } });
  });

  // All RealWorld routes are namespaced under /api.
  app.register(
    async (api) => {
      await userRoutes(api);
      await profileRoutes(api);
      await articleRoutes(api);
      await commentRoutes(api);
      await tagRoutes(api);
    },
    { prefix: "/api" },
  );

  return app;
}

