import { signToken } from "./auth.js";

// These types mirror what the routes fetch from Prisma with the includes below.
interface UserRecord {
  id: number;
  email: string;
  username: string;
  bio: string | null;
  image: string | null;
}

export function userJson(user: UserRecord) {
  return {
    user: {
      email: user.email,
      username: user.username,
      bio: user.bio,
      image: user.image,
      token: signToken({ id: user.id, username: user.username }),
    },
  };
}

interface AuthorRecord {
  username: string;
  bio: string | null;
  image: string | null;
  followedBy?: { id: number }[];
}

export function profilePayload(author: AuthorRecord, currentUserId: number | null) {
  return {
    username: author.username,
    bio: author.bio,
    image: author.image,
    following: currentUserId
      ? (author.followedBy ?? []).some((u) => u.id === currentUserId)
      : false,
  };
}

export function profileJson(author: AuthorRecord, currentUserId: number | null) {
  return { profile: profilePayload(author, currentUserId) };
}

interface ArticleRecord {
  slug: string;
  title: string;
  description: string;
  body: string;
  createdAt: Date;
  updatedAt: Date;
  tags: { name: string }[];
  author: AuthorRecord;
  favoritedBy: { id: number }[];
}

export function articlePayload(article: ArticleRecord, currentUserId: number | null) {
  return {
    slug: article.slug,
    title: article.title,
    description: article.description,
    body: article.body,
    tagList: article.tags.map((t) => t.name).sort(),
    createdAt: article.createdAt.toISOString(),
    updatedAt: article.updatedAt.toISOString(),
    favorited: currentUserId
      ? article.favoritedBy.some((u) => u.id === currentUserId)
      : false,
    favoritesCount: article.favoritedBy.length,
    author: profilePayload(article.author, currentUserId),
  };
}

export function articleJson(article: ArticleRecord, currentUserId: number | null) {
  return { article: articlePayload(article, currentUserId) };
}

interface CommentRecord {
  id: number;
  body: string;
  createdAt: Date;
  updatedAt: Date;
  author: AuthorRecord;
}

export function commentPayload(comment: CommentRecord, currentUserId: number | null) {
  return {
    id: comment.id,
    body: comment.body,
    createdAt: comment.createdAt.toISOString(),
    updatedAt: comment.updatedAt.toISOString(),
    author: profilePayload(comment.author, currentUserId),
  };
}

export function commentJson(comment: CommentRecord, currentUserId: number | null) {
  return { comment: commentPayload(comment, currentUserId) };
}

// Prisma include fragments shared by the routes so responses always carry the
// relations the view helpers rely on.
export const articleInclude = {
  tags: true,
  author: { include: { followedBy: { select: { id: true } } } },
  favoritedBy: { select: { id: true } },
} as const;

export const commentInclude = {
  author: { include: { followedBy: { select: { id: true } } } },
} as const;

